 useEffect(()=>{const p=new URLSearchParams(window.location.search);const payment=p.get("payment");const sessionId=p.get("session_id");if(payment==="cancelled"){setCheckoutState("error");setPaymentMessage("Payment was cancelled.");return}if(payment==="success"){setCheckoutState("starting");setPaymentMessage("Payment returned successfully. Verifying the Stripe payment…");if(!sessionId){setCheckoutState("error");setPaymentMessage("Stripe returned without a Checkout Session ID. Payment was not verified.");return}fetch("/api/checkout-status?session_id="+encodeURIComponent(sessionId)).then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||"Payment verification failed.");if(d.paid){setCheckoutState("success");const testMode=d.livemode!==true;setPaymentMessage((testMode?"Test payment verified: ":"Payment verified: ")+"$"+Number(d.amountTotal||0).toFixed(2)+" received for "+(d.offer||"your order")+" · Order "+(d.orderId||d.sessionId)+(testMode?" · TEST MODE — not counted as live revenue.":""));try{const key="aibb_stripe_"+d.sessionId;if(!localStorage.getItem(key)){localStorage.setItem(key,"1");setLedger(v=>[{id:Date.now(),amount:Number(d.amountTotal||0).toFixed(2),source:"Stripe · "+(d.orderId||d.sessionId)+(testMode?" · Test":" · Live"),status:testMode?"Test":"Verified",time:new Date().toLocaleString()},...v].slice(0,100));logActivity("Stripe Payment",(testMode?"Test verified $":"Live verified $")+Number(d.amountTotal||0).toFixed(2)+" · "+(d.orderId||d.sessionId),testMode?"Test":"Verified")}}catch(e){console.warn("Local ledger update skipped",e)}}else{setCheckoutState("error");setPaymentMessage("Stripe checkout returned, but payment is not marked paid yet ("+(d.paymentStatus||d.status||"pending")+"). No revenue was recorded.");}}).catch(e=>{setCheckoutState("error");setPaymentMessage(e?.message||"Payment verification failed.");});}},[]);
